def busca_binaria(valores, alvo):
    baixo,alto = 0,len(valores)-1
    while baixo <= alto:
        meio = (baixo+alto)//2
        if valores[meio] == alvo:
            return meio
        if valores[meio] < alvo:
            baixo = meio+1
        else:
            alto = meio-1
    return -1
assert busca_binaria([4],4) == 0
assert busca_binaria([4],3) == -1
assert busca_binaria([2,4,6],2) == 0
assert busca_binaria([2,4,6],6) == 2
